import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.Dp3tugkT.js";const p=JSON.parse('{"title":"F5: TanStack Query Server State & Redux Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"features/F5-tanstack-query-redux-dashboard.md","filePath":"features/F5-tanstack-query-redux-dashboard.md"}'),s={name:"features/F5-tanstack-query-redux-dashboard.md"};function o(d,t,i,c,u,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="f5-tanstack-query-server-state-redux-dashboard" tabindex="-1">F5: TanStack Query Server State &amp; Redux Dashboard <a class="header-anchor" href="#f5-tanstack-query-server-state-redux-dashboard" aria-label="Permalink to &quot;F5: TanStack Query Server State &amp; Redux Dashboard&quot;">​</a></h1><h2 id="_1-description-frontend-architecture" tabindex="-1">1. Description &amp; Frontend Architecture <a class="header-anchor" href="#_1-description-frontend-architecture" aria-label="Permalink to &quot;1. Description &amp; Frontend Architecture&quot;">​</a></h2><p>The user interface pairs Redux Toolkit for synchronous client state (user authentication, active modals) with TanStack Query for asynchronous server state management (link history, click counters, mutation states).</p><h2 id="_2-state-management-split" tabindex="-1">2. State Management Split <a class="header-anchor" href="#_2-state-management-split" aria-label="Permalink to &quot;2. State Management Split&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State Type</th><th>Library</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Client UI State</strong></td><td>Redux Toolkit (<code>@reduxjs/toolkit</code>)</td><td>Current user session, toast alerts, theme preferences</td></tr><tr><td><strong>Server Cache State</strong></td><td>TanStack Query (<code>@tanstack/react-query</code>)</td><td>URL listings, click stats, optimistic mutations, refetching</td></tr></tbody></table><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;On the frontend, I decoupled client UI state from asynchronous server state. I used Redux Toolkit strictly for synchronous user credentials and UI modal toggles, while delegating all data fetching, caching, and background refetching to TanStack Query. When an author creates a new short link, TanStack Query immediately invalidates the &#39;userUrls&#39; query key, triggering an instant background re-render without requiring manual state synchronization. This prevents stale analytics and ensures a responsive user experience.&quot;</p>',7)])])}const m=e(s,[["render",o]]);export{p as __pageData,m as default};
